code_mappings.python:
for i in range(6):
    print(i)  # 0, 1, 2, 3, 4, 5

for i in range(2, 10, 2):
    print(i)  # 2, 4, 6, 8

code_mappings.java:
for (int i = 0; i < 6; i++) {
    System.out.println(i);  // 0-5
}

for (int i = 2; i < 10; i += 2) {
    System.out.println(i);  // 2, 4, 6, 8
}

code_mappings.python:
for i in range(10):
    if i == 3:
        continue  # salta el 3
    if i == 7:
        break     # termina en el 7
    print(i)  # 0, 1, 2, 4, 5, 6

code_mappings.java:
for (int i = 0; i < 10; i++) {
    if (i == 3) continue;
    if (i == 7) break;
    System.out.println(i);
}

code_mappings.python:
for i in range(6):
    print(i)
else:
    print("¡Bucle completado!")
# El else se ejecuta al terminar normalmente

code_mappings.java:
// Java NO tiene for...else
for (int i = 0; i < 6; i++) {
    System.out.println(i);
}
System.out.println("Bucle completado!");
// Se simula poniendo el código después del for

